// apps/api/src/modules/crm/tasks/task-port.ts — owner: Dev 6 (MOD-TASK; Contracts §4.3)
// The real TaskPort, built once in server.ts and handed to every module that needs it (leads for the first-contact task,
// lender cases for the lender-query task). It runs in the caller's transaction and does not need the caller to hold
// task.create: the task is generated by the workflow, not requested by the user.
import type { TaskPort } from '@dsa/contracts';
import { SqlTaskRepository, type TaskRepository } from './repository';
import { TaskService, type TaskServiceDeps } from './task-service';

export function createTaskPort(
  deps: Omit<TaskServiceDeps, 'repository'> & { repository?: TaskRepository },
): TaskPort {
  const service = new TaskService({ ...deps, repository: deps.repository ?? new SqlTaskRepository() });
  return { createTask: (tx, ctx, cmd) => service.createTaskPort(tx, ctx, cmd) };
}
